import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    order_info = {} # id -> {'side':..., 'qty':..., 'active':..., 'price':...}
    trades = []
    seq_counter = 0

    def push_order(side, oid, price, qty, seq):
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        seq_counter += 1
        seq = seq_counter
        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = pop_valid(opp_heap)
            if top is None:
                break

            if side == 'buy':
                actual_price = top[0]  # sell_heap stores positive price
            else:
                actual_price = -top[0]  # buy_heap stores negative price

            if typ != 'market':
                if side == 'buy' and actual_price > price:
                    break
                if side == 'sell' and actual_price < price:
                    break

            resting_id = top[2]
            resting_info = order_info[resting_id]
            trade_qty = min(remaining, resting_info['qty'])

            if side == 'buy':
                trades.append([oid, resting_id, actual_price, trade_qty])
            else:
                trades.append([resting_id, oid, actual_price, trade_qty])

            resting_info['qty'] -= trade_qty
            remaining -= trade_qty

            if resting_info['qty'] == 0:
                resting_info['active'] = False
                heapq.heappop(opp_heap)
            # else: partial fill, stays at top for next iteration

        if typ == 'limit' and remaining > 0:
            order_info[oid] = {'side': side, 'qty': remaining, 'active': True, 'price': price}
            push_order(side, oid, price, remaining, seq)
        # ioc/market remainder is discarded, no resting entry needed

    return trades

